actions.script:
const given = name => (typeof ec.context[name] === 'undefined' || ec.context[name] === '' ? null : ec.context[name])
let checked = null
let refusal = null
ec.message.pushErrors()
try {
    checked = ec.service.sync().name('mantle.work.EventRegistrationServices.checkIn#Registration').parameters({
        registrationPolicyId: given('registrationPolicyId'), entryCode: given('entryCode') || given('entryCode_scanText'),
        registrationId: given('registrationId'), reason: given('reason'), override: given('override') === 'Y',
        expectedRevision: given('expectedRevision'), operationKey: given('operationKey')
    }).requireNewTransaction(true).call()
    if (ec.message.hasError()) refusal = ec.message.getErrorsString()
} catch (error) {
    refusal = String(error.message || error)
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}
if (refusal) {
    // a refusal names its reason (CODE: message); anything else is a failure the door cannot fix here
    const coded = /\b([A-Z][A-Z0-9_]{3,}):\s*([^\n]*)/.exec(refusal)
    if (!coded) ec.logger.warn('Event check-in failed: ' + refusal)
    ec.message.addMessage(coded ? ec.l10n.localize(coded[2]) : ec.l10n.localize('Not checked in. Try again.'), 'danger')
} else {
    const decision = checked.decision || {}
    ec.message.addMessage((decision.attendeeText || '') + ': ' + (checked.repeated
        ? ec.l10n.localize('already checked in at') + ' ' + (decision.attendance?.checkInTime || '')
        : ec.l10n.localize('checked in') + (decision.ticketText ? ' · ' + decision.ticketText : '')), checked.repeated ? 'warning' : 'success')
}

onDevice = !!UserSecurityChecks.currentDevice()
canStaff = !onDevice && !!marketing.capabilities?.checkInRead
offerList = []
if (canStaff && !registrationPolicyId && workEffortId) {
    // an event's offers to choose (published or closed); one alone is chosen
    ec.message.pushErrors()
    try {
        const setup = ec.service.sync().name('mantle.work.EventRegistrationServices.get#EventSetup')
            .parameters({workEffortId}).requireNewTransaction(true).call() || {}
        offerList = Array.from(setup.offers || []).filter(offer => offer.statusId === 'ErpPublished' || offer.statusId === 'ErpClosed')
    } catch (error) {
        offerList = []
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
    if (offerList.length === 1) registrationPolicyId = offerList[0].registrationPolicyId
}
desk = null
candidates = []
notAvailable = null
if (registrationPolicyId && (onDevice || canStaff)) {
    ec.message.pushErrors()
    try {
        const previewed = ec.service.sync().name('mantle.work.EventRegistrationServices.preview#CheckIn')
            .parameters({registrationPolicyId, term: canStaff && term ? term : null}).requireNewTransaction(true).call() || {}
        if (ec.message.hasError()) notAvailable = ec.message.getErrorsString()
        desk = previewed.desk || null
        candidates = Array.from(previewed.candidates || [])
    } catch (error) {
        notAvailable = String(error.message || error)
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
    if (notAvailable) {
        const coded = /\b([A-Z][A-Z0-9_]{3,}):\s*([^\n]*)/.exec(notAvailable)
        notAvailable = coded ? coded[2] : ec.l10n.localize('Check-in is not available now.')
    }
}
eventsPath = marketing.sharedLinks?.['Events/Events'] || null
lookupValues = {registrationPolicyId, term}
deskText = desk ? desk.checkedInCount + (desk.expectedCount != null ? ' ' + ec.l10n.localize('of') + ' ' + desk.expectedCount : '') + ' '
    + ec.l10n.localize('checked in') : ''
if (sri.getRenderMode() == 'html') {
    // the html page: the theme's style sheets, the qvt client's files and this screen as an island (WebrootPublic.qvt.js)
    const qvtLib = ec.resource.script('component://webroot/screen/includes/QvtConfig.js')
    const localeTag = String(ec.user.locale || 'en_US').replace('_', '-')
    const quasarLang = qvtLib.quasarLangOf(localeTag)
    const sheets = Array.from(sri.getThemeValues('STRT_STYLESHEET'))
    const scripts = ['/libs/vue/vue.global.prod.js', '/libs/quasar/quasar.umd.prod.js', '/libs/quasar/lang/' + quasarLang + '.umd.prod.js']
    if (sheets.some(sheet => String(sheet).includes('/libs/material-symbols/'))) scripts.push('/libs/quasar/icon-set/material-symbols-outlined.umd.prod.js')
    scripts.push('/js/MoquiLib.js', '/js/MoquiL10n.js', '/js/WebrootVue.qvt.render.js', '/js/WebrootVue.qvt.js', '/js/WebrootPublic.qvt.js')
    const version = '?v=' + ec.web.getResourceDistinctValue()
    const href = location => WebUtilities.encodeHtml(sri.buildUrl(location).url + version)
    doorHead = sheets.map(sheet => '<link rel="stylesheet" href="' + href(sheet) + '">').join('')
    doorScripts = scripts.map(script => '<script src="' + href(script) + '"></script>').join('')
    doorLang = WebUtilities.encodeHtml(localeTag)
    doorTitle = WebUtilities.encodeHtml(ec.l10n.localize('Event check-in'))
    const island = {
        shell: 'island', sessionToken: ec.web.sessionToken, appRootPath: '', locale: localeTag, timeZone: ec.user.timeZone,
        quasarLang: quasarLang.replace(/-([a-zA-Z])/g, (m, ch) => ch.toUpperCase()),
        quasar: {notify: {progress: true, position: 'top', timeout: 6000}},
        qvt: {build: 'compiler', handles: ['merged-fragment', 'static-template']},
        route: {name: 'event-check-in', basePath: sri.buildUrl('.').path, title: ec.l10n.localize('Event check-in'), renderModes: ['qvt']},
        context: {}, labels: {loading: ec.l10n.localize('Loading'), notFound: ec.l10n.localize('This check-in is not available.')}
    }
    doorIsland = JSON.stringify(island).split('<').join('\\u003c')
}
